-- =========================================================================
-- ptz_master.lua - PTZ for mpv windows started by PTZ Master
-- Generated by PTZ Master v9.0.91  (Lua template 1.0)
--
-- THIS FILE IS REGENERATED ON EVERY START - do not edit it in place.
-- To customise: use the environment variables below, remap keys in
-- ~/.config/mpv/input.conf, or copy the file under another name.
-- =========================================================================
-- DIGITAL (always works, any camera - mpv software zoom / pan):
--   Alt+,  / Alt+.            zoom out / zoom in
--   Alt+UP/DOWN/LEFT/RIGHT    pan; the canvas follows the key, exactly like
--                             the arrows in PTZ Master's PAN mode
--   Alt+/                     reset (also Alt+?, Ctrl+Alt+r, Alt+r, Shift+r)
--
-- MOTOR (needs PTZ_IP + PTZ_RAW_SCRIPT; the camera must have a real motor):
--   Ctrl+Alt+arrows  or  Ctrl+Shift+arrows     pan / tilt
--   Ctrl+Alt+i / Ctrl+Alt+o                    zoom in / out (motor zoom)
--   Ctrl+Shift+s / Ctrl+Shift+h                stop / home
--   Ctrl+Shift+1..9                            go to preset N
--
-- ENVIRONMENT (all optional - PTZ Master sets them per camera):
--   CAM_NAME  PTZ_IP  PTZ_USER  PTZ_PASS  PTZ_RAW_SCRIPT
--   PTZ_SPEED  PTZ_DURATION_MS  PTZ_ZOOM_DURATION_MS
--   DIGITAL_STEP_ZOOM  DIGITAL_STEP_PAN
--   DIGITAL_ZOOM_MIN  DIGITAL_ZOOM_MAX  DIGITAL_PAN_MAX
--   (CAM_IP / CAM_USER / CAM_PASS are accepted as aliases)
--
-- NOTE: Lua has no unary +.  Use dzoom(z_step), not dzoom(+z_step).
-- =========================================================================

local msg = require 'mp.msg'

-- --- Config (environment) ------------------------------------------------
local function getenv_nonempty(name)
    local v = os.getenv(name)
    if v == nil or v == "" then return nil end
    return v
end
local function getenv_num(name, default)
    return tonumber(os.getenv(name) or "") or default
end

local cam_name = getenv_nonempty("CAM_NAME") or "camera"
local ip       = getenv_nonempty("CAM_IP")   or getenv_nonempty("PTZ_IP")   or ""
local user     = getenv_nonempty("CAM_USER") or getenv_nonempty("PTZ_USER") or "admin"
local pass_env = os.getenv("PTZ_PASS")            -- nil = unset, "" = empty password
local pass     = os.getenv("CAM_PASS") or pass_env or ""
local script   = getenv_nonempty("PTZ_RAW_SCRIPT") or ""
local HAS_MOTOR = (ip ~= "" and script ~= "")
-- When PTZ_PASS is set the raw script reads it from the inherited environment,
-- so the password never appears on a command line (ps / /proc/PID/cmdline).
local PASS_VIA_ENV = (pass_env ~= nil)

local m_speed = getenv_num("PTZ_SPEED",            0.5)
local m_dur   = getenv_num("PTZ_DURATION_MS",      300)
local m_zoom  = getenv_num("PTZ_ZOOM_DURATION_MS", 500)
local z_step  = getenv_num("DIGITAL_STEP_ZOOM",    0.1)
local p_step  = getenv_num("DIGITAL_STEP_PAN",     0.05)
local Z_MIN   = getenv_num("DIGITAL_ZOOM_MIN",     -1.0)
local Z_MAX   = getenv_num("DIGITAL_ZOOM_MAX",     3.0)
local P_MAX   = getenv_num("DIGITAL_PAN_MAX",      0.5)

local function clamp(v, lo, hi) return math.max(lo, math.min(hi, v)) end

-- --- Motor helpers -------------------------------------------------------
-- Every motor command is one external process (~150-250 ms).  Holding a key
-- would queue a backlog and the camera would keep moving after release, so:
--   * at most ONE command runs at a time,
--   * while it runs, only the NEWEST further request is remembered,
--   * stop / home / presets are "urgent": they run at once and drop the queue.
local inflight, pending = 0, nil

local function build_cmd(args)
    local cmd = { script, "--ip", ip, "--user", user }
    if not PASS_VIA_ENV then
        cmd[#cmd + 1] = "--pass"
        cmd[#cmd + 1] = pass
    end
    for _, a in ipairs(args) do cmd[#cmd + 1] = tostring(a) end
    return cmd
end

local function run_motor(args)
    inflight = inflight + 1
    mp.command_native_async({
        name           = "subprocess",
        args           = build_cmd(args),
        capture_stdout = true,
        capture_stderr = true,
        playback_only  = false,
    }, function(success, res, err)
        inflight = inflight - 1
        local status = (res and res.status) or -1
        if (not success) or status ~= 0 then
            local detail = (res and res.stderr and res.stderr ~= "" and res.stderr) or err or "error"
            msg.warn("PTZ motor: " .. tostring(detail))
            mp.osd_message("Motor error", 1)
        end
        if inflight == 0 and pending then
            local nxt = pending
            pending = nil
            run_motor(nxt)
        end
    end)
end

local function mcall(args, urgent)
    if urgent then
        pending = nil
        run_motor(args)
    elseif inflight == 0 then
        run_motor(args)
    else
        pending = args
    end
end

local function mmove(dir, label)
    mcall({ "move-" .. dir, m_speed, m_dur })
    mp.osd_message("Motor " .. label, 0.3)
end
local function mzoom(dir, label)
    mcall({ "zoom-" .. dir, m_speed, m_zoom })
    mp.osd_message("Motor " .. label, 0.3)
end

-- --- Digital helpers -----------------------------------------------------
local function dzoom(d)
    local cur = mp.get_property_number("video-zoom") or 0
    local new = clamp(cur + d, Z_MIN, Z_MAX)
    mp.set_property_number("video-zoom", new)
    mp.osd_message(string.format("Zoom x%.2f", 2 ^ new), 0.4)
end

-- dx/dy are "canvas motion" as the user expects; signs are already adjusted
-- for mpv's video-pan semantics at the call site (see DIGITAL PAN below).
local function dpan(dx, dy, label)
    local cx = mp.get_property_number("video-pan-x") or 0
    local cy = mp.get_property_number("video-pan-y") or 0
    local nx = clamp(cx + dx, -P_MAX, P_MAX)
    local ny = clamp(cy + dy, -P_MAX, P_MAX)
    mp.set_property_number("video-pan-x", nx)
    mp.set_property_number("video-pan-y", ny)
    mp.osd_message(string.format("Pan %s  x:%+.2f y:%+.2f", label or "", nx, ny), 0.4)
end

local function dreset()
    mp.set_property_number("video-zoom", 0)
    mp.set_property_number("video-pan-x", 0)
    mp.set_property_number("video-pan-y", 0)
    mp.osd_message("Reset: zoom=1 pan=0/0", 0.6)
end

-- --- Binding helper ------------------------------------------------------
local function fbind(key, name, fn, rpt)
    local opts = { repeatable = rpt or false }
    local ok
    if mp.add_forced_key_binding then
        ok = pcall(mp.add_forced_key_binding, key, name, fn, opts)
    else
        ok = pcall(mp.add_key_binding, key, name, fn, opts)
    end
    if ok then msg.verbose("bind OK   " .. key .. " -> " .. name)
    else       msg.warn(   "bind FAIL " .. key .. " -> " .. name) end
end

-- =========================================================================
-- MOTOR  (Ctrl+Alt family + Ctrl+Shift for stop / home / presets)
-- =========================================================================
if HAS_MOTOR then
    fbind("Ctrl+Alt+UP",    "m-up-1",    function() mmove("up",    "↑") end, true)
    fbind("Ctrl+Alt+DOWN",  "m-down-1",  function() mmove("down",  "↓") end, true)
    fbind("Ctrl+Alt+LEFT",  "m-left-1",  function() mmove("left",  "←") end, true)
    fbind("Ctrl+Alt+RIGHT", "m-right-1", function() mmove("right", "→") end, true)

    -- alternative for window managers that take Ctrl+Alt
    fbind("Ctrl+Shift+UP",    "m-up-2",    function() mmove("up",    "↑") end, true)
    fbind("Ctrl+Shift+DOWN",  "m-down-2",  function() mmove("down",  "↓") end, true)
    fbind("Ctrl+Shift+LEFT",  "m-left-2",  function() mmove("left",  "←") end, true)
    fbind("Ctrl+Shift+RIGHT", "m-right-2", function() mmove("right", "→") end, true)

    fbind("Ctrl+Alt+i", "m-zi", function() mzoom("in",  "zoom+") end, true)
    fbind("Ctrl+Alt+o", "m-zo", function() mzoom("out", "zoom-") end, true)

    fbind("Ctrl+Shift+s", "m-stop", function()
        mcall({ "stop" }, true); mp.osd_message("Motor stop", 0.5) end)
    fbind("Ctrl+Shift+h", "m-home", function()
        mcall({ "home" }, true); mp.osd_message("Motor home", 0.5) end)
    for n = 1, 9 do
        fbind("Ctrl+Shift+" .. n, "m-pre" .. n, function()
            mcall({ "preset-goto", n }, true); mp.osd_message("Preset " .. n, 0.5) end)
    end
end

-- =========================================================================
-- DIGITAL ZOOM:  "," reads as "less" (out), "." as "more" (in)
-- =========================================================================
fbind("Alt+,", "d-zo", function() dzoom(-z_step) end, true)
fbind("Alt+.", "d-zi", function() dzoom(z_step)  end, true)

-- =========================================================================
-- DIGITAL PAN - the canvas follows the key (same as PTZ Master PAN mode):
--   mpv video-pan-y: positive moves the video DOWN  -> we see the UPPER part
--   mpv video-pan-x: positive moves the video RIGHT -> we see the LEFT part
--   UP    -> pan-y +     DOWN  -> pan-y -
--   LEFT  -> pan-x +     RIGHT -> pan-x -
-- =========================================================================
fbind("Alt+UP",    "d-pu", function() dpan(0, p_step,  "↑") end, true)
fbind("Alt+DOWN",  "d-pd", function() dpan(0, -p_step, "↓") end, true)
fbind("Alt+LEFT",  "d-pl", function() dpan(p_step, 0,  "←") end, true)
fbind("Alt+RIGHT", "d-pr", function() dpan(-p_step, 0, "→") end, true)

-- =========================================================================
-- RESET (Alt+/ primary + backups; Alt+0 is taken by mpv's window-scale)
-- =========================================================================
fbind("Alt+/",      "d-reset1", dreset, false)
fbind("Alt+?",      "d-reset2", dreset, false)
fbind("Ctrl+Alt+r", "d-reset3", dreset, false)
fbind("Alt+r",      "d-reset4", dreset, false)
fbind("Shift+r",    "d-reset5", dreset, false)

-- =========================================================================
-- STARTUP
-- =========================================================================
if HAS_MOTOR then
    msg.info(string.format("PTZ Master v9.0.91: %s | digital + motor (%s)", cam_name, ip))
else
    msg.info(string.format("PTZ Master v9.0.91: %s | digital only", cam_name))
end
msg.info("zoom=Alt+,(out) Alt+.(in) | pan=Alt+arrows | reset=Alt+/")
